INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'An Accidental Invention', 'Many great things were invented by accident. The potato chip is one of them. It was invented in 1853 by a cook named George Crum. One day, a customer said his fried potatoes were too thick. Crum was not happy, so he cut the potatoes very thin and fried them. He thought the customer would hate them. But the customer loved them! Soon these thin, crispy chips became popular. Today, potato chips are eaten all over the world. This story shows that some of the best things are made by mistake. A small accident can change the world.', '说明文', 98, '[{"q": "When was the potato chip invented?", "answer": "D", "options": ["In 1900.", "In 1835.", "In 1953.", "In 1853."], "explanation": "原文:invented in 1853"}, {"q": "Who invented the potato chip?", "answer": "A", "options": ["George Crum.", "A teacher.", "A customer.", "A farmer."], "explanation": "原文:by a cook named George Crum"}, {"q": "Why did Crum cut the potatoes thin?", "answer": "C", "options": ["He was hungry.", "He had no choice.", "The customer said they were too thick.", "He liked thin chips."], "explanation": "原文:too thick"}, {"q": "How did the customer feel about the thin chips?", "answer": "A", "options": ["He loved them.", "He was angry.", "He hated them.", "He was bored."], "explanation": "原文:the customer loved them"}, {"q": "What does the story show?", "answer": "D", "options": ["Cooking is hard.", "Customers are rude.", "Potatoes are cheap.", "Some of the best things are made by mistake."], "explanation": "主旨:意外造就好东西"}]'::jsonb, '[{"word": "customer", "cn": "顾客"}, {"word": "crispy", "cn": "酥脆的"}, {"word": "popular", "cn": "受欢迎的"}]'::jsonb, 3, '9', 'U6');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Who Invented Basketball?', 'Basketball is loved by millions of people, but do you know who invented it? It was invented in 1891 by a Canadian teacher named James Naismith. At that time, he worked at a school in the US. The winter was cold, and students could not play outside. Naismith wanted a new indoor game. He divided the students into two teams and used a basket on the wall. The first game was played with a soccer ball. Soon the game became popular. Today, basketball is played all over the world, and Naismith is looked up to as a hero.', '记叙文', 98, '[{"q": "When was basketball invented?", "answer": "A", "options": ["In 1891.", "In 1981.", "In 1900.", "In 1819."], "explanation": "原文:invented in 1891"}, {"q": "Who invented basketball?", "answer": "C", "options": ["A doctor.", "George Crum.", "James Naismith.", "A student."], "explanation": "原文:by James Naismith"}, {"q": "Why did Naismith want a new game?", "answer": "A", "options": ["Students could not play outside in winter.", "He was bored.", "He needed money.", "He liked baseball."], "explanation": "原文:winter was cold...could not play outside"}, {"q": "What was the first game played with?", "answer": "D", "options": ["A tennis ball.", "A baseball.", "A basketball.", "A soccer ball."], "explanation": "原文:played with a soccer ball"}, {"q": "How do people see Naismith today?", "answer": "D", "options": ["As a cook.", "As a teacher only.", "As a player.", "As a hero."], "explanation": "原文:looked up to as a hero"}]'::jsonb, '[{"word": "divide", "cn": "分开"}, {"word": "indoor", "cn": "室内的"}, {"word": "hero", "cn": "英雄"}]'::jsonb, 3, '9', 'U6');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'The Story of Tea', 'Tea is one of the most popular drinks in the world. It is said that tea was discovered by accident. A long time ago, a Chinese ruler named Shen Nong was boiling water under a tree. Suddenly, some leaves fell into the water. The water changed color and gave off a nice smell. Shen Nong tasted it and found it delicious. This was how tea was first made. Later, tea was brought to Korea and Japan. By the 17th century, it was also traded to Western countries. Today, tea is drunk by people everywhere, but it all began with a happy accident.', '说明文', 102, '[{"q": "How was tea discovered?", "answer": "C", "options": ["By a teacher.", "On purpose.", "By accident.", "In a shop."], "explanation": "原文:discovered by accident"}, {"q": "Who discovered tea?", "answer": "A", "options": ["Shen Nong.", "A farmer.", "George Crum.", "James Naismith."], "explanation": "原文:a ruler named Shen Nong"}, {"q": "What fell into the water?", "answer": "C", "options": ["Some flowers.", "Some fruit.", "Some leaves.", "Some grass."], "explanation": "原文:some leaves fell"}, {"q": "Where was tea brought after China?", "answer": "C", "options": ["The US and UK.", "France.", "Korea and Japan.", "Germany."], "explanation": "原文:brought to Korea and Japan"}, {"q": "By when was tea traded to the West?", "answer": "B", "options": ["By the 7th century.", "By the 17th century.", "By 1891.", "By 1853."], "explanation": "原文:By the 17th century"}]'::jsonb, '[{"word": "discover", "cn": "发现"}, {"word": "boil", "cn": "煮沸"}, {"word": "trade", "cn": "贸易;交易"}]'::jsonb, 3, '9', 'U6');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Inventions Change Our Lives', 'Inventions have changed our daily lives in many ways. Think about the light bulb. Before it was invented, people used candles at night. Now our homes are filled with light. The telephone was invented so that people could talk over long distances. Today, mobile phones are used by almost everyone. Even small things, like the zipper, make life easier. It was invented in 1893 and is now used on clothes and bags everywhere. Some inventions were made on purpose, and some were made by accident. But all of them share one thing: they were created to solve problems and make our lives better.', '议论文', 103, '[{"q": "What did people use before the light bulb?", "answer": "A", "options": ["Candles.", "Phones.", "Zippers.", "Computers."], "explanation": "原文:used candles at night"}, {"q": "Why was the telephone invented?", "answer": "A", "options": ["So people could talk over long distances.", "To play music.", "To tell time.", "To take photos."], "explanation": "原文:talk over long distances"}, {"q": "When was the zipper invented?", "answer": "D", "options": ["In 1983.", "In 1853.", "In 1839.", "In 1893."], "explanation": "原文:invented in 1893"}, {"q": "Where is the zipper used now?", "answer": "B", "options": ["Only on books.", "On clothes and bags.", "Only on shoes.", "Only on cars."], "explanation": "原文:used on clothes and bags"}, {"q": "What do all the inventions share?", "answer": "A", "options": ["They were created to solve problems.", "They are Chinese.", "They are expensive.", "They are old."], "explanation": "原文:created to solve problems"}]'::jsonb, '[{"word": "invention", "cn": "发明"}, {"word": "distance", "cn": "距离"}, {"word": "solve", "cn": "解决"}]'::jsonb, 3, '9', 'U6');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'My Science Project', 'Last month, our class had a science project about inventions. Each student was asked to make something useful. My friend Tom made a small lamp. It was powered by the sun, so no electricity was needed. A girl named Lily made a bag that was made from old clothes. My project was a clock that was made of used wood. The teacher asked us how our things were produced. We explained that everything was made by hand from waste materials. The teacher was very pleased. She said that good inventions are not always made of expensive things. Sometimes the best ideas come from simple materials.', '记叙文', 105, '[{"q": "What was each student asked to make?", "answer": "D", "options": ["A painting.", "A song.", "A story.", "Something useful."], "explanation": "原文:make something useful"}, {"q": "What powered Tom''s lamp?", "answer": "B", "options": ["Wind.", "The sun.", "Electricity.", "A battery."], "explanation": "原文:powered by the sun"}, {"q": "What was the writer''s clock made of?", "answer": "C", "options": ["Glass.", "Metal.", "Used wood.", "Old clothes."], "explanation": "原文:made of used wood"}, {"q": "How were the projects produced?", "answer": "B", "options": ["Bought online.", "By hand from waste materials.", "By machines.", "In a factory."], "explanation": "原文:made by hand from waste"}, {"q": "What did the teacher say about good inventions?", "answer": "C", "options": ["They are hard.", "They take years.", "They are not always made of expensive things.", "They need money."], "explanation": "原文:not always made of expensive things"}]'::jsonb, '[{"word": "project", "cn": "项目"}, {"word": "electricity", "cn": "电"}, {"word": "pleased", "cn": "高兴的"}]'::jsonb, 3, '9', 'U6');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Invention Museum Guide', 'WELCOME TO THE INVENTION MUSEUM! Discover how everyday things were invented. OPENING HOURS: 9:00 a.m. to 5:00 p.m., Tuesday to Sunday. FLOOR 1 — DAILY LIFE: See how the telephone, the light bulb, and the fridge were invented. Many were created by accident! FLOOR 2 — SPORTS: Learn how basketball and other games were invented and who invented them. FLOOR 3 — FOOD: Find out how potato chips and ice cream were first made. FREE GUIDE: A free guidebook is given to every visitor. TICKETS: Adults 20 yuan, students 10 yuan. Come and see how great ideas changed the world!', '应用文', 100, '[{"q": "When is the museum open?", "answer": "D", "options": ["Only Monday.", "Every day.", "Only weekends.", "Tuesday to Sunday."], "explanation": "原文:Tuesday to Sunday"}, {"q": "What can you see on Floor 1?", "answer": "C", "options": ["Basketball.", "Potato chips.", "The telephone, light bulb, and fridge.", "Cars."], "explanation": "原文:Floor 1 — Daily Life"}, {"q": "Where can you learn about basketball?", "answer": "B", "options": ["Floor 1.", "Floor 2.", "The shop.", "Floor 3."], "explanation": "原文:Floor 2 — Sports"}, {"q": "What is given to every visitor?", "answer": "B", "options": ["A free toy.", "A free guidebook.", "A free ticket.", "A free drink."], "explanation": "原文:free guidebook is given"}, {"q": "How much is a student ticket?", "answer": "B", "options": ["Free.", "10 yuan.", "15 yuan.", "20 yuan."], "explanation": "原文:students 10 yuan"}]'::jsonb, '[{"word": "discover", "cn": "发现"}, {"word": "guide", "cn": "指南;向导"}, {"word": "visitor", "cn": "参观者"}]'::jsonb, 3, '9', 'U6');
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U6', 'The First Ice Cream', 'Ice cream is loved by people all over the world. But do you know how it was (1)____? Long ago, there were no fridges. People could not (2)____ food cold easily. It is said that ice cream was first (3)____ in China. Ice and milk were (4)____ together to make a cold, sweet food. Later, this idea was (5)____ to other countries. In Italy, new kinds of ice cream were (6)____. People added fruit and sugar to make it (7)____. Today, ice cream is (8)____ in many flavors. It is (9)____ for cooling us down in summer. A simple cold food has (10)____ people happy for hundreds of years.', 109, 3, '[{"q": "1", "answer": "D", "options": ["eaten", "sold", "grown", "invented"], "explanation": "被发明 invented"}, {"q": "2", "answer": "D", "options": ["lose", "throw", "cut", "keep"], "explanation": "保持冷 keep cold"}, {"q": "3", "answer": "B", "options": ["sold", "made", "eaten", "lost"], "explanation": "被制作 made"}, {"q": "4", "answer": "A", "options": ["mixed", "dropped", "thrown", "broken"], "explanation": "被混合 mixed"}, {"q": "5", "answer": "A", "options": ["brought", "kept", "eaten", "lost"], "explanation": "被带到 brought"}, {"q": "6", "answer": "C", "options": ["eaten", "sold", "created", "lost"], "explanation": "被创造 created"}, {"q": "7", "answer": "C", "options": ["colder", "worse", "better", "smaller"], "explanation": "更好 better"}, {"q": "8", "answer": "B", "options": ["thrown", "sold", "lost", "kept"], "explanation": "被卖 sold"}, {"q": "9", "answer": "B", "options": ["thrown", "used", "broken", "lost"], "explanation": "用于 used for"}, {"q": "10", "answer": "A", "options": ["made", "lost", "sold", "kept"], "explanation": "使…快乐 made people happy"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U6', 'How the Telephone Was Invented', 'The telephone is one of the most important (1)____ in history. It was (2)____ in 1876 by Alexander Graham Bell. Before that, people could only (3)____ letters to talk over long distances. This took a long (4)____. Bell wanted to find a way for people to (5)____ to each other quickly. After much hard work, the first telephone was (6)____. When it was (7)____ for the first time, people were amazed. Soon, telephones were (8)____ in many homes. Today, mobile phones are (9)____ by almost everyone. The telephone has (10)____ the way we live and talk.', 96, 3, '[{"q": "1", "answer": "D", "options": ["products", "prices", "colors", "inventions"], "explanation": "发明 inventions"}, {"q": "2", "answer": "B", "options": ["sold", "invented", "eaten", "grown"], "explanation": "被发明 invented"}, {"q": "3", "answer": "A", "options": ["send", "lose", "eat", "cut"], "explanation": "寄信 send letters"}, {"q": "4", "answer": "A", "options": ["time", "place", "color", "money"], "explanation": "花时间 time"}, {"q": "5", "answer": "B", "options": ["walk", "talk", "run", "sleep"], "explanation": "交谈 talk"}, {"q": "6", "answer": "B", "options": ["sold", "made", "eaten", "lost"], "explanation": "被制造 made"}, {"q": "7", "answer": "A", "options": ["used", "lost", "thrown", "broken"], "explanation": "被使用 used"}, {"q": "8", "answer": "D", "options": ["sold", "lost", "eaten", "put"], "explanation": "被安装 put"}, {"q": "9", "answer": "C", "options": ["kept", "broken", "used", "lost"], "explanation": "被使用 used"}, {"q": "10", "answer": "C", "options": ["sold", "lost", "changed", "kept"], "explanation": "改变了 changed"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U6', 'A Useful Mistake', 'Some great things are (1)____ by mistake. One example is the sticky note. A scientist was trying to make a strong (2)____. But the glue he made was very (3)____. It could stick to paper but came off easily. At first, he thought his work was a (4)____. But later, another person had an idea. The weak glue could be (5)____ to make notes that stick and come off. So the sticky note was (6)____. Today, sticky notes are (7)____ by students and workers everywhere. They are (8)____ for leaving short messages. This story shows that a (9)____ can become something useful. We should never (10)____ up after a mistake.', 110, 3, '[{"q": "1", "answer": "C", "options": ["eaten", "sold", "made", "lost"], "explanation": "被做出 made"}, {"q": "2", "answer": "A", "options": ["glue", "game", "color", "price"], "explanation": "胶水 glue"}, {"q": "3", "answer": "D", "options": ["big", "cold", "strong", "weak"], "explanation": "弱的 weak"}, {"q": "4", "answer": "A", "options": ["failure", "game", "success", "color"], "explanation": "失败 failure"}, {"q": "5", "answer": "B", "options": ["broken", "used", "thrown", "lost"], "explanation": "被用来 used"}, {"q": "6", "answer": "D", "options": ["eaten", "lost", "sold", "created"], "explanation": "被创造 created"}, {"q": "7", "answer": "B", "options": ["broken", "used", "lost", "kept"], "explanation": "被使用 used"}, {"q": "8", "answer": "B", "options": ["broken", "used", "lost", "thrown"], "explanation": "用于 used for"}, {"q": "9", "answer": "A", "options": ["mistake", "song", "color", "price"], "explanation": "错误 mistake"}, {"q": "10", "answer": "C", "options": ["lose", "take", "give", "keep"], "explanation": "放弃 give up"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U6', 'The History of Paper', 'Paper is used (1)____ writing, drawing, and many other things. But how was it (2)____? Paper was (3)____ in China about two thousand years ago. Before paper, words were (4)____ on bamboo or silk. But these were heavy or (5)____. A man named Cai Lun found a way to make paper from cheap (6)____ like grass and old cloth. His paper was light and (7)____. Soon, this great invention was (8)____ to other countries. Books could then be (9)____ more easily. Paper has (10)____ the way people share knowledge. It is one of the greatest inventions in history.', 98, 3, '[{"q": "1", "answer": "A", "options": ["for", "by", "with", "to"], "explanation": "used for"}, {"q": "2", "answer": "B", "options": ["grown", "invented", "sold", "eaten"], "explanation": "被发明 invented"}, {"q": "3", "answer": "D", "options": ["sold", "lost", "eaten", "made"], "explanation": "被制造 made"}, {"q": "4", "answer": "C", "options": ["eaten", "grown", "written", "sold"], "explanation": "被写 written"}, {"q": "5", "answer": "C", "options": ["short", "cheap", "expensive", "cold"], "explanation": "昂贵的 expensive"}, {"q": "6", "answer": "D", "options": ["colors", "games", "prices", "materials"], "explanation": "材料 materials"}, {"q": "7", "answer": "B", "options": ["sour", "cheap", "heavy", "cold"], "explanation": "便宜的 cheap"}, {"q": "8", "answer": "B", "options": ["eaten", "brought", "lost", "kept"], "explanation": "被带到 brought"}, {"q": "9", "answer": "A", "options": ["made", "sold", "lost", "kept"], "explanation": "被制作 made"}, {"q": "10", "answer": "A", "options": ["changed", "kept", "lost", "sold"], "explanation": "改变了 changed"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U6', 'The Olympics', 'The Olympic Games are (1)____ by millions of people around the world. But do you know how they were (2)____? The Olympics were first (3)____ in ancient Greece more than two thousand years ago. They were (4)____ to honor the gods. Later, the games were (5)____ for many years. Then in 1896, the modern Olympics were (6)____ again in Greece. Since then, the games have been (7)____ every four years. Athletes from many countries are (8)____ to take part. The Olympics are now (9)____ for bringing people together in peace. They are (10)____ as a symbol of friendship and sport.', 100, 3, '[{"q": "1", "answer": "B", "options": ["lost", "watched", "sold", "eaten"], "explanation": "被观看 watched"}, {"q": "2", "answer": "C", "options": ["kept", "eaten", "started", "lost"], "explanation": "开始 started"}, {"q": "3", "answer": "A", "options": ["held", "eaten", "lost", "sold"], "explanation": "被举办 held"}, {"q": "4", "answer": "C", "options": ["broken", "thrown", "used", "lost"], "explanation": "用来 used to honor"}, {"q": "5", "answer": "A", "options": ["stopped", "started", "eaten", "sold"], "explanation": "被停止 stopped"}, {"q": "6", "answer": "D", "options": ["lost", "sold", "eaten", "held"], "explanation": "被举办 held"}, {"q": "7", "answer": "A", "options": ["held", "kept", "lost", "broken"], "explanation": "被举办 held"}, {"q": "8", "answer": "B", "options": ["lost", "welcomed", "thrown", "broken"], "explanation": "被欢迎 welcomed"}, {"q": "9", "answer": "B", "options": ["kept", "known", "lost", "sold"], "explanation": "以…著称 known for"}, {"q": "10", "answer": "D", "options": ["sold", "kept", "lost", "seen"], "explanation": "被看作 seen as"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U6', 'Things Used Every Day', 'Many things that are (1)____ every day were invented long ago. Look at the clock. It is (2)____ for telling time. Before clocks, people used the sun to (3)____ the time. The umbrella is another useful thing. It is (4)____ for keeping off rain and sun. It was first (5)____ in China. The fridge is (6)____ for keeping food cold and fresh. Before fridges, food could not be (7)____ for long. Even the simple key is (8)____ for opening and closing locks. All these things were (9)____ to make our lives easier. We should be (10)____ to the people who invented them.', 102, 3, '[{"q": "1", "answer": "B", "options": ["broken", "used", "thrown", "lost"], "explanation": "被使用 used"}, {"q": "2", "answer": "A", "options": ["used", "kept", "broken", "lost"], "explanation": "用于 used for"}, {"q": "3", "answer": "B", "options": ["lose", "tell", "cut", "eat"], "explanation": "知道时间 tell time"}, {"q": "4", "answer": "C", "options": ["lost", "thrown", "used", "broken"], "explanation": "用于 used for"}, {"q": "5", "answer": "C", "options": ["eaten", "lost", "made", "sold"], "explanation": "被制造 made"}, {"q": "6", "answer": "D", "options": ["broken", "kept", "lost", "used"], "explanation": "用于 used for"}, {"q": "7", "answer": "A", "options": ["kept", "sold", "lost", "eaten"], "explanation": "被保存 kept"}, {"q": "8", "answer": "B", "options": ["thrown", "used", "broken", "lost"], "explanation": "用于 used for"}, {"q": "9", "answer": "D", "options": ["eaten", "sold", "lost", "created"], "explanation": "被创造 created"}, {"q": "10", "answer": "A", "options": ["thankful", "tired", "angry", "sad"], "explanation": "感激的 thankful"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U6 听力·对话 When Was It Invented', '九年级 Unit6 听力·发明与被动语态', 2, 'W: This is a great museum. When was the telephone invented?
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U6 听力·短文 The Potato Chip', '九年级 Unit6 听力·发明与被动语态', 2, 'Let me tell you how the potato chip was invented.
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U6 听力·对话 What Is It Used For', '九年级 Unit6 听力·发明与被动语态', 2, 'W: What a strange tool! What is it used for?
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U6 听力·短文 The Story of Tea', '九年级 Unit6 听力·发明与被动语态', 2, 'Tea was discovered by accident long ago.
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U6 听力·对话 A Science Project', '九年级 Unit6 听力·发明与被动语态', 2, 'W: What did you make for your science project?
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U6 听力·短文 Inventions in Our Life', '九年级 Unit6 听力·发明与被动语态', 2, 'Many inventions make our daily life easier.
INSERT INTO public.junior_writing_prompts (id, grade, topic, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, difficulty, title_en, high_sentences, error_pairs, paragraph_template, volume, unit) SELECT gen_random_uuid(), 9, 'An Invention That Changed the World', '用被动语态介绍一项你认为重要的发明(如电话、电灯、拉链、薯片等)。写清它何时、由谁发明,以及它的用途和影响。60词左右。', 'Write a short passage on the topic: "An Invention That Changed the World".', '["这项发明是什么", "它何时、由谁发明的(was invented in...by...)", "它的用途(be used for...)", "它给生活带来的影响"]'::jsonb, 70, 100, 'The telephone is one of the greatest inventions in history. It was invented in 1876 by Alexander Graham Bell. Before it was invented, people could only send letters over long distances. The telephone is used for talking to people far away. Today, mobile phones are used by almost everyone. This great invention has changed the way we live and made our life much easier.', 'content:含发明/时间发明者/用途/影响四要点(4分)；language:正确使用被动语态 was/were invented/used(3分)；structure:语句通顺、衔接得当(2分)；wordcount:词数达标、书写规范(1分)', 3, 'An Invention That Changed the World', '["was/were invented in ...", "was invented by ...", "be used for + doing", "make our life easier", "change the world", "one of the greatest inventions"]'::jsonb, '[]'::jsonb, '要点:这项发明是什么；它何时、由谁发明的(was invented in...by...)；它的用途(be used for...)；它给生活带来的影响', '9', 'U6' WHERE NOT EXISTS (SELECT 1 FROM public.junior_writing_prompts WHERE volume='9' AND unit='U6' AND topic='An Invention That Changed the World');
